package com.assetflow.notification.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Service;
@Service public class NotificationEmailService { private final JavaMailSender sender; private final String username; public NotificationEmailService(JavaMailSender sender,@Value("${spring.mail.username:}") String username){this.sender=sender;this.username=username;} public boolean send(String to,String subject,String body){if(username==null||username.isBlank()||to==null||to.isBlank())return false;SimpleMailMessage m=new SimpleMailMessage();m.setFrom(username);m.setTo(to);m.setSubject(subject);m.setText(body);sender.send(m);return true;} }
